mapper.select:
select
wrm.*
from wms_return_manufactured wrm
left join wms_return_detail_manufactured wrdm on wrm.id = wrdm.return_manufactured_id and wrdm.bool_delete_enum = 0
where wrm.bool_delete_enum = 0

    and wrm.serial_number like concat('%',#{serialNumber},'%')


    and wrm.applicant_name like concat('%',#{personName},'%')


    and wrdm.basic_class = #{basicClass}


    and wrdm.project_id = #{projectId}


    
        and wrm.applicant_time >= #{applicationTime[0]}
    
    
        and wrm.applicant_time <= #{applicationTime[1]}
    


    
        and wrm.review_pass_time >= #{reviewPassTime[0]}
    
    
        and wrm.review_pass_time <= #{reviewPassTime[1]}
    


    and wrdm.review_status = #{reviewStatus}

group by wrm.id
